test('renderInvoiceText orders lines: number, customer, items, vat, voucher, total, due, paid', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'TEST', amount: 100 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const withPayment = {
    ...issued,
    payments: [{ amount: 500, date: '2025-01-20' }],
  };

  const result = renderInvoiceText(withPayment);
  const text = result.value;
  const lines = text.split('\n');

  const numberLine = lines[0];
  const customerLine = lines[1];
  const itemLine = lines.find(l => l.includes('Design work'));
  const vatLine = lines.find(l => l.includes('VAT'));
  const voucherLine = lines.find(l => l.includes('Voucher'));
  const totalLine = lines.find(l => l.startsWith('Total'));
  const dueLine = lines.find(l => l.startsWith('Due'));
  const paidLine = lines.find(l => l.startsWith('Paid'));

  assert(lines.indexOf(numberLine) < lines.indexOf(customerLine));
  assert(lines.indexOf(customerLine) < lines.indexOf(itemLine));
  assert(lines.indexOf(itemLine) < lines.indexOf(vatLine));
  assert(lines.indexOf(vatLine) < lines.indexOf(voucherLine));
  assert(lines.indexOf(voucherLine) < lines.indexOf(totalLine));
  assert(lines.indexOf(totalLine) < lines.indexOf(dueLine));
  assert(lines.indexOf(dueLine) < lines.indexOf(paidLine));
});

