    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'WELCOME10', amount: 1000 }).value;
  const result = renderInvoiceText(withVoucher);
  const text = result.value;
  const lines = text.split('\n');

  assert.match(text, /Voucher: -€10\.00/);
  const voucherLineIndex = lines.findIndex(l => l.includes('Voucher'));
  const totalLineIndex = lines.findIndex(l => l.includes('Total'));
  assert(voucherLineIndex < totalLineIndex);
});

test('renderInvoiceText does not show voucher when not present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const result = renderInvoiceText(invoice);
  const text = result.value;
