  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const result = renderInvoiceText(invoice);
  const text = result.value;
  assert.match(text, /Due: 2025-02-14$/m);
});

test('renderInvoiceText does not show due date when not present (draft)', () => {
  const invoice = {
    customerId: 'C-001',
    status: 'draft',
    lines: [{ qty: 1, name: 'Item', unitPrice: 1000, discountPercent: 0, vatRate: 20 }],
  };

  const result = renderInvoiceText(invoice);
  const text = result.value;
  assert.equal(text.includes('Due:'), false);
});

test('renderInvoiceText shows amount paid when there are payments', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
